# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人连续两次说“你和其他人一样根本不听我”，咨询师感到被误解并想解释自己。请说明如何处理这一关系事件。
## 📌 参考思路
参考要点：暂停自我辩护；承认并邀请当事人描述具体体验；识别可能的对抗型破裂；检查咨询师是否推进、打断或误解；承担适当责任并修复；在安全后再试探连接其他关系模式；不把当事人的批评全部解释为投射。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid);
update public.chapter_review_notes set content = '# 【第十一章 领悟阶段技术整合】
## 🎯 本章目标
整合挑战、解释和关系工作，根据当事人反应灵活选择技术，使新的理解既有深度又可被当事人使用。
## 🧭 学习主线
回顾探索材料 → 选择领悟目标 → 决定挑战/解释/关系工作 → 观察反应 → 调整深度 → 形成行动方向。
---PAGE---
# 【领悟目标】
## 🧠 考试定义
领悟阶段希望当事人形成的具体新理解，应与咨询目标和重复模式直接相关。
## 💬 如何向来访者解释
我们这一步想理解的是批评出现时你为何会迅速退出。
## 🧩 应用情境
把目标表述为“理解为何一被批评就退出关系”。
## ⚠️ 易错点
追求宏大人格解释而缺少可工作的焦点。
---PAGE---
# 【技术匹配】
## 🧠 考试定义
依据问题性质、联盟状态和当事人准备度选择挑战、解释或关系技术。
## 💬 如何向来访者解释
我会根据此刻最需要解决的是理解、矛盾还是关系来选择工作方式。
## 🧩 应用情境
信念矛盾突出时挑战，材料分散时解释，关系紧张时先修复。
## ⚠️ 易错点
固定使用咨询师最喜欢的技术，不顾会谈需要。
---PAGE---
# 【由浅入深】
## 🧠 考试定义
从当事人已觉察的材料开始，逐步连接到更深层需要和模式。
## 💬 如何向来访者解释
我们先从你已经能看到的循环开始，再决定是否继续深入。
## 🧩 应用情境
先讨论当前循环，再连接早期关系经验。
## ⚠️ 易错点
一开始就给出深层人格或童年解释。
---PAGE---
# 【反应监测】
## 🧠 考试定义
持续观察当事人的认知、情绪、身体和关系反应，判断技术是否合适。
## 💬 如何向来访者解释
你的反应会告诉我们这个方向是否合适，我们可以随时调整。
## 🧩 应用情境
当挑战后出现羞耻和撤退时立即放慢并修复。
## ⚠️ 易错点
只按预定计划推进，不理会当事人反应。
---PAGE---
# 【领悟巩固】
## 🧠 考试定义
通过总结、命名、举例和寻找例外，使新理解更清晰、稳定和可记忆。
## 💬 如何向来访者解释
你能否用自己的话说说今天形成的新理解，以及它在哪些场景出现？
## 🧩 应用情境
让当事人用自己的话总结模式并找出最近例子。
## ⚠️ 易错点
咨询师总结完就认为当事人已经掌握。
---PAGE---
# 【替代性理解】
## 🧠 考试定义
在不否定原经验的基础上形成更灵活、功能更好的解释。
## 💬 如何向来访者解释
我们不是强迫你乐观，而是寻找更符合证据、也更有选择空间的理解。
## 🧩 应用情境
从“我失败所以没价值”转向“失败触发了条件性价值规则”。
## ⚠️ 易错点
用空泛积极口号覆盖真实困难。
---PAGE---
# 【向行动过渡】
## 🧠 考试定义
把领悟转化为具体可观察的改变目标、选择点和练习方向。
## 💬 如何向来访者解释
如果这个理解对你有用，我们再一起决定下一次可以尝试怎样不同。
## 🧩 应用情境
识别触发点后制定下次暂停旧反应的计划。
## ⚠️ 易错点
在当事人尚未认同理解时立刻布置行动。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人已理解自己通过讨好避免冲突，但听到咨询师挑战后突然沉默并说“算了，我就是没用”。请说明领悟技术如何整合与调整。
## 📌 参考思路
参考要点：暂停继续挑战并监测羞耻和联盟反应；共情并处理当下关系影响；澄清挑战是否被体验为批评；恢复安全后用较浅、试探性解释理解讨好的保护功能；让当事人用自己的话总结；得到认同后再形成行动方向。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, '# 【第十一章 领悟阶段技术整合】
## 🎯 本章目标
整合挑战、解释和关系工作，根据当事人反应灵活选择技术，使新的理解既有深度又可被当事人使用。
## 🧭 学习主线
回顾探索材料 → 选择领悟目标 → 决定挑战/解释/关系工作 → 观察反应 → 调整深度 → 形成行动方向。
---PAGE---
# 【领悟目标】
## 🧠 考试定义
领悟阶段希望当事人形成的具体新理解，应与咨询目标和重复模式直接相关。
## 💬 如何向来访者解释
我们这一步想理解的是批评出现时你为何会迅速退出。
## 🧩 应用情境
把目标表述为“理解为何一被批评就退出关系”。
## ⚠️ 易错点
追求宏大人格解释而缺少可工作的焦点。
---PAGE---
# 【技术匹配】
## 🧠 考试定义
依据问题性质、联盟状态和当事人准备度选择挑战、解释或关系技术。
## 💬 如何向来访者解释
我会根据此刻最需要解决的是理解、矛盾还是关系来选择工作方式。
## 🧩 应用情境
信念矛盾突出时挑战，材料分散时解释，关系紧张时先修复。
## ⚠️ 易错点
固定使用咨询师最喜欢的技术，不顾会谈需要。
---PAGE---
# 【由浅入深】
## 🧠 考试定义
从当事人已觉察的材料开始，逐步连接到更深层需要和模式。
## 💬 如何向来访者解释
我们先从你已经能看到的循环开始，再决定是否继续深入。
## 🧩 应用情境
先讨论当前循环，再连接早期关系经验。
## ⚠️ 易错点
一开始就给出深层人格或童年解释。
---PAGE---
# 【反应监测】
## 🧠 考试定义
持续观察当事人的认知、情绪、身体和关系反应，判断技术是否合适。
## 💬 如何向来访者解释
你的反应会告诉我们这个方向是否合适，我们可以随时调整。
## 🧩 应用情境
当挑战后出现羞耻和撤退时立即放慢并修复。
## ⚠️ 易错点
只按预定计划推进，不理会当事人反应。
---PAGE---
# 【领悟巩固】
## 🧠 考试定义
通过总结、命名、举例和寻找例外，使新理解更清晰、稳定和可记忆。
## 💬 如何向来访者解释
你能否用自己的话说说今天形成的新理解，以及它在哪些场景出现？
## 🧩 应用情境
让当事人用自己的话总结模式并找出最近例子。
## ⚠️ 易错点
咨询师总结完就认为当事人已经掌握。
---PAGE---
# 【替代性理解】
## 🧠 考试定义
在不否定原经验的基础上形成更灵活、功能更好的解释。
## 💬 如何向来访者解释
我们不是强迫你乐观，而是寻找更符合证据、也更有选择空间的理解。
## 🧩 应用情境
从“我失败所以没价值”转向“失败触发了条件性价值规则”。
## ⚠️ 易错点
用空泛积极口号覆盖真实困难。
---PAGE---
# 【向行动过渡】
## 🧠 考试定义
把领悟转化为具体可观察的改变目标、选择点和练习方向。
## 💬 如何向来访者解释
如果这个理解对你有用，我们再一起决定下一次可以尝试怎样不同。
## 🧩 应用情境
识别触发点后制定下次暂停旧反应的计划。
## ⚠️ 易错点
在当事人尚未认同理解时立刻布置行动。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人已理解自己通过讨好避免冲突，但听到咨询师挑战后突然沉默并说“算了，我就是没用”。请说明领悟技术如何整合与调整。
## 📌 参考思路
参考要点：暂停继续挑战并监测羞耻和联盟反应；共情并处理当下关系影响；澄清挑战是否被体验为批评；恢复安全后用较浅、试探性解释理解讨好的保护功能；让当事人用自己的话总结；得到认同后再形成行动方向。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid);
update public.chapter_review_notes set content = '# 【第十二章 行动阶段概述】
## 🎯 本章目标
理解行动阶段如何把领悟转化为目标、方案、技能和现实生活中的练习，并通过反馈持续调整。
## 🧭 学习主线
确认行动准备度 → 设定具体目标 → 生成多个方案 → 评估可行性与风险 → 选择小步骤 → 实施、反馈和修订。
---PAGE---
# 【行动阶段】
## 🧠 考试定义
把探索和领悟转化为新行为、技能、环境调整与持续练习的阶段。
## 💬 如何向来访者解释
我们会把理解变成一个你愿意尝试、可以观察结果的小步骤。
## 🧩 应用情境
围绕已识别的回避模式设计一次可完成的沟通尝试。
## ⚠️ 易错点
把行动等同于咨询师给建议或当事人立刻做巨大改变。
---PAGE---
# 【行动准备度】
## 🧠 考试定义
当事人对改变的意愿、信心、资源、风险和现实条件的综合状态。
## 💬 如何向来访者解释
在决定行动前，我们先看看你有多想改变、有什么资源和顾虑。
## 🧩 应用情境
行动前询问重要性、信心和可能障碍。
## ⚠️ 易错点
当事人口头同意就认为已经准备好。
---PAGE---
# 【具体目标】
## 🧠 考试定义
清晰、可观察、现实且与当事人价值一致的改变方向。
## 💬 如何向来访者解释
我们把目标写成具体行为，这样你能判断是否发生了变化。
## 🧩 应用情境
把“更自信”转为“本周会议至少表达一次不同意见”。
## ⚠️ 易错点
目标由咨询师决定，或使用无法观察的空泛词。
---PAGE---
# 【方案生成】
## 🧠 考试定义
在评估前尽量产生多个可能行动，扩大选择而不是过早锁定一个答案。
## 💬 如何向来访者解释
我们先不急着判断，尽可能列出几种做法，再比较。
## 🧩 应用情境
共同列出沟通、准备、寻求支持和环境调整等方案。
## ⚠️ 易错点
只给一个“正确方案”并要求执行。
---PAGE---
# 【方案评估】
## 🧠 考试定义
比较不同方案的收益、成本、风险、资源需求和价值一致性。
## 💬 如何向来访者解释
每个方案都有收益和代价，我们一起看哪些最符合你的现实和价值。
## 🧩 应用情境
对离职方案同时评估经济、健康、关系和替代选择。
## ⚠️ 易错点
只看短期舒服程度或咨询师个人偏好。
---PAGE---
# 【小步骤】
## 🧠 考试定义
把复杂改变拆成难度适中、时间明确且容易反馈的最小可行行动。
## 💬 如何向来访者解释
我们先设计一个足够小、你有把握完成的步骤。
## 🧩 应用情境
先练习写下请求，再选择低风险对象表达。
## ⚠️ 易错点
一次要求彻底改变，失败后归因为缺乏动力。
---PAGE---
# 【行动反馈循环】
## 🧠 考试定义
实施后记录结果、情绪和障碍，再据此巩固、调整或更换方案。
## 💬 如何向来访者解释
无论是否完成，结果都会提供信息，帮助我们调整下一步。
## 🧩 应用情境
下次会谈比较预期与实际结果并修订计划。
## ⚠️ 易错点
任务完成与否是唯一指标，未完成就算失败。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人理解自己害怕拒绝，却提出“从明天起我要对所有人说不”。请评估其行动准备度并把目标转化为合理计划。
## 📌 参考思路
参考要点：认可改变愿望但评估信心、风险和资源；把全或无目标具体化；生成多个练习方案；从低风险关系和小请求开始；明确时间、行为和反馈记录；讨论失败与复发；由当事人选择，不以咨询师命令替代合作。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid;
