update public.chapter_review_notes set content = '# 【第十五章 使用三阶段模型与当事人工作】
## 🎯 本章目标
在真实个案中灵活使用探索、领悟和行动，进行个案概念化、阶段判断、技术选择、反馈和过程调整。
## 🧭 学习主线
建立关系与评估 → 形成初步概念化 → 判断当前阶段任务 → 选择技术 → 监测反应与联盟 → 循环调整。
---PAGE---
# 【个案概念化】
## 🧠 考试定义
整合问题、诱发因素、维持机制、资源、文化和目标形成可修正的工作假设。
## 💬 如何向来访者解释
这是我们目前对问题如何形成和维持的理解，会随着新信息不断修正。
## 🧩 应用情境
把症状、关系模式、优势和环境压力放入同一理解框架。
## ⚠️ 易错点
把概念化当作固定诊断标签或一次完成的结论。
---PAGE---
# 【阶段判断】
## 🧠 考试定义
根据当事人的需要和会谈任务判断此刻更需要探索、领悟还是行动。
## 💬 如何向来访者解释
阶段不是固定课表，我们会根据此刻最需要的工作来选择。
## 🧩 应用情境
情绪材料不清时回到探索，模式清楚后进入领悟，准备充分时行动。
## ⚠️ 易错点
按会谈次数机械规定阶段。
---PAGE---
# 【阶段往返】
## 🧠 考试定义
三阶段可以循环和回退，新行动可能带来新的探索与领悟。
## 💬 如何向来访者解释
尝试后的新体验会带来更多理解，我们可以随时回到前面。
## 🧩 应用情境
任务失败后回到探索障碍和理解模式。
## ⚠️ 易错点
进入行动后就不能再讨论情绪或关系。
---PAGE---
# 【技术意图】
## 🧠 考试定义
咨询师在使用技术前明确希望促进的过程目标，并检查是否服务当事人。
## 💬 如何向来访者解释
每一种提问和回应都应有清楚目的，并根据你的反应调整。
## 🧩 应用情境
提问前判断是为澄清、深化还是满足自己的好奇。
## ⚠️ 易错点
只看技术形式，不考虑使用目的和影响。
---PAGE---
# 【当事人反应】
## 🧠 考试定义
当事人在认知、情绪、行为和关系上的即时回应，是判断技术效果的重要信息。
## 💬 如何向来访者解释
你的反应会告诉我们这个方式是否有帮助。
## 🧩 应用情境
技术后出现开放、沉默或撤退时分别调整。
## ⚠️ 易错点
只要技术理论正确就不需要观察反应。
---PAGE---
# 【过程反馈】
## 🧠 考试定义
定期询问当事人对关系、目标、任务、节奏和帮助程度的看法。
## 💬 如何向来访者解释
请告诉我今天哪部分有帮助、哪部分需要我做得不同。
## 🧩 应用情境
每次会谈末询问最有帮助和需要改变的部分。
## ⚠️ 易错点
只在结束时进行满意度调查。
---PAGE---
# 【整合一致性】
## 🧠 考试定义
不同技术应围绕共同概念化、目标和关系逻辑协调使用。
## 💬 如何向来访者解释
我们使用的不同方法会围绕同一个目标，而不是彼此冲突。
## 🧩 应用情境
所有阶段技术都指向减少回避并增加真实表达。
## ⚠️ 易错点
从不同流派随意拼接互相矛盾的做法。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人在会谈中理解了回避模式并同意行动任务，但执行后焦虑显著升高并开始质疑咨询关系。请用三阶段模型重新安排工作。
## 📌 参考思路
参考要点：暂停机械推进行动；评估风险和焦虑程度；回到探索行动后的体验和关系破裂；修复联盟；更新概念化，理解任务难度、信念和环境障碍；重新判断阶段；必要时缩小任务或先训练调节技能；持续使用过程反馈。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, '# 【第十五章 使用三阶段模型与当事人工作】
## 🎯 本章目标
在真实个案中灵活使用探索、领悟和行动，进行个案概念化、阶段判断、技术选择、反馈和过程调整。
## 🧭 学习主线
建立关系与评估 → 形成初步概念化 → 判断当前阶段任务 → 选择技术 → 监测反应与联盟 → 循环调整。
---PAGE---
# 【个案概念化】
## 🧠 考试定义
整合问题、诱发因素、维持机制、资源、文化和目标形成可修正的工作假设。
## 💬 如何向来访者解释
这是我们目前对问题如何形成和维持的理解，会随着新信息不断修正。
## 🧩 应用情境
把症状、关系模式、优势和环境压力放入同一理解框架。
## ⚠️ 易错点
把概念化当作固定诊断标签或一次完成的结论。
---PAGE---
# 【阶段判断】
## 🧠 考试定义
根据当事人的需要和会谈任务判断此刻更需要探索、领悟还是行动。
## 💬 如何向来访者解释
阶段不是固定课表，我们会根据此刻最需要的工作来选择。
## 🧩 应用情境
情绪材料不清时回到探索，模式清楚后进入领悟，准备充分时行动。
## ⚠️ 易错点
按会谈次数机械规定阶段。
---PAGE---
# 【阶段往返】
## 🧠 考试定义
三阶段可以循环和回退，新行动可能带来新的探索与领悟。
## 💬 如何向来访者解释
尝试后的新体验会带来更多理解，我们可以随时回到前面。
## 🧩 应用情境
任务失败后回到探索障碍和理解模式。
## ⚠️ 易错点
进入行动后就不能再讨论情绪或关系。
---PAGE---
# 【技术意图】
## 🧠 考试定义
咨询师在使用技术前明确希望促进的过程目标，并检查是否服务当事人。
## 💬 如何向来访者解释
