insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8c04ed6e-2bc5-566a-9dc8-7055410f3773'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '下列哪一概念最符合这一描述：“助人者与当事人通过合作，促进当事人探索、理解与改变的专业互动过程。”？', '[{"key":"A","text":"助人"},{"key":"B","text":"心理治疗"},{"key":"C","text":"共同因素"},{"key":"D","text":"治疗联盟"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“助人”。应用提示：当事人带着困扰进入会谈时，助人者先建立合作并澄清其需要，而不是立即给建议。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6929437e-1644-54b0-a501-395a5739391b'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '下列哪一概念最符合这一描述：“在良好关系基础上，运用心理学理论与技术帮助相对功能完整者处理发展、适应与心理困扰的专业过程。”？', '[{"key":"A","text":"共同因素"},{"key":"B","text":"心理咨询"},{"key":"C","text":"治疗联盟"},{"key":"D","text":"三阶段模型"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“心理咨询”。应用提示：向初次来访者说明咨询需要共同参与，通常包含评估、目标、工作与回顾。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2221df20-9b0c-5957-8f68-8beed4d96e48'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '会谈情境：发现问题严重程度或风险超出当前服务范围时，需要评估并讨论转介或联合治疗。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"三阶段模型"},{"key":"B","text":"助人效果评估"},{"key":"C","text":"心理治疗"},{"key":"D","text":"助人"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“心理治疗”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d6a21409-cc11-567a-a4dc-e1e4ce9704b8'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '会谈情境：技术选择之前先检查联盟、目标一致性和当事人的希望感。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"助人效果评估"},{"key":"B","text":"助人"},{"key":"C","text":"心理咨询"},{"key":"D","text":"共同因素"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“共同因素”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ccfa20e2-9380-56d0-b381-b4bf430fe0ac'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '会谈情境：当当事人反复不完成任务时，先核对目标与任务是否真正得到共同认可。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"治疗联盟"},{"key":"B","text":"助人"},{"key":"C","text":"心理咨询"},{"key":"D","text":"心理治疗"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“治疗联盟”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fc704e8b-effc-5e2f-9f4e-5d2cf46ecef3'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '咨询师向来访者说明：“我们通常先探索发生了什么，再理解其中模式，最后尝试新的行动；必要时会回到前面。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"心理咨询"},{"key":"B","text":"三阶段模型"},{"key":"C","text":"心理治疗"},{"key":"D","text":"共同因素"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“三阶段模型”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d60bd800-15d7-5eda-9a91-8355b814dd16'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'single', '围绕“助人效果评估”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"只凭咨询师感觉良好或当事人礼貌回应判断有效。"},{"key":"B","text":"定期询问会谈是否有帮助、目标是否变化，并根据反馈调整。"},{"key":"C","text":"依据概念进行判断：通过当事人反馈、目标进展、功能变化和会谈过程信息持续判断助人是否有效。"},{"key":"D","text":"向来访者说明：我会定期询问哪些部分有帮助、哪些没有，以便及时调整。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：只凭咨询师感觉良好或当事人礼貌回应判断有效。。规范依据是：通过当事人反馈、目标进展、功能变化和会谈过程信息持续判断助人是否有效。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('726b57fb-f41f-540b-9ca2-56d668c1718d'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人带着困扰进入会谈时，助人者先建立合作并澄清其需要，而不是立即给建议。"},{"key":"B","text":"心理咨询不是替你做决定，而是帮助你更清楚地理解自己并练习新的应对。"},{"key":"C","text":"认为咨询和治疗存在绝对边界，或任何咨询师都能处理所有临床问题。"},{"key":"D","text":"认为只有某一学派的独特技术决定全部疗效。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“助人”的规范应用，B体现向来访者说明“心理咨询”时的合作性表达；C、D分别是“心理治疗”和“共同因素”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b7da3b51-cb26-51b6-afae-3c8b5b7fb1f4'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"发现问题严重程度或风险超出当前服务范围时，需要评估并讨论转介或联合治疗。"},{"key":"B","text":"方法很重要，但我们之间是否信任、目标是否一致、你是否能在生活中尝试改变同样重要。"},{"key":"C","text":"把表面配合或对咨询师的顺从当作稳定联盟。"},{"key":"D","text":"把三个阶段理解成只能单向推进、不能回到前一阶段的固定程序。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“心理治疗”的规范应用，B体现向来访者说明“共同因素”时的合作性表达；C、D分别是“治疗联盟”和“三阶段模型”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7b0a4b8e-f0c2-5d5a-9188-6891140a4de5'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当当事人反复不完成任务时，先核对目标与任务是否真正得到共同认可。"},{"key":"B","text":"我们通常先探索发生了什么，再理解其中模式，最后尝试新的行动；必要时会回到前面。"},{"key":"C","text":"只凭咨询师感觉良好或当事人礼貌回应判断有效。"},{"key":"D","text":"把助人等同于替当事人解决问题或替其做决定。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“治疗联盟”的规范应用，B体现向来访者说明“三阶段模型”时的合作性表达；C、D分别是“助人效果评估”和“助人”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7bccc33c-e716-5199-9f12-bf18173cf082'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'blank', '请依据本章学习主线补全工作流程：界定助人任务 → ____ → 识别阶段目标 → 选择阶段技术 → 持续观察当事人反应与效果。', NULL, '{"correct":["建立合作关系"]}'::jsonb, '本章流程中该环节是“建立合作关系”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('796cfddf-d570-575c-9a09-6c275b2e4f39'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'blank', '请依据本章学习主线补全工作流程：界定助人任务 → 建立合作关系 → 识别阶段目标 → ____ → 持续观察当事人反应与效果。', NULL, '{"correct":["选择阶段技术"]}'::jsonb, '本章流程中该环节是“选择阶段技术”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('587d0236-2afc-5017-890a-9ad0c64e4ba4'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'blank', '请依据本章学习主线补全工作流程：界定助人任务 → 建立合作关系 → 识别阶段目标 → 选择阶段技术 → ____。', NULL, '{"correct":["持续观察当事人反应与效果"]}'::jsonb, '本章流程中该环节是“持续观察当事人反应与效果”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1da9bc14-9b44-503b-8e32-36d88d232611'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'short', '简答题：助人导引包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：助人、心理咨询、心理治疗、共同因素、治疗联盟、三阶段模型、助人效果评估。\n2）本章目标：理解助人、心理咨询与心理治疗的基本边界，掌握共同因素、助人效果以及探索—领悟—行动三阶段模型。\n3）作答不能只罗列名称，还应依据“界定助人任务 → 建立合作关系 → 识别阶段目标 → 选择阶段技术 → 持续观察当事人反应与效果。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('69bf6d5d-9ab0-5791-a470-54afd24c0505'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'short', '简答题：说明“助人”与“共同因素”各自的含义，并指出在助人导引中的应用要点。', NULL, '{"reference":"参考要点：\n1）助人：助人者与当事人通过合作，促进当事人探索、理解与改变的专业互动过程。\n2）共同因素：不同取向都可能共享的疗效因素，包括关系、希望与期待、情绪唤起、自我效能、学习体验和实践机会。\n3）应用：当事人带着困扰进入会谈时，助人者先建立合作并澄清其需要，而不是立即给建议。\n4）应用：技术选择之前先检查联盟、目标一致性和当事人的希望感。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('19ca86bc-f137-5c2d-9a7e-23c1c0e1c202'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'short', '简答题：如果来访者询问“为什么要使用治疗联盟和三阶段模型”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）治疗联盟：我们需要确认目标是你真正想做的，方法也对你有意义；不同意可以直接告诉我。\n2）三阶段模型：我们通常先探索发生了什么，再理解其中模式，最后尝试新的行动；必要时会回到前面。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3bc3e7d3-467e-5f11-923d-2eed2896714d'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'case', '案例题：一位当事人第一次来访便要求咨询师“直接告诉我该不该离职”，并表示只要得到一个答案就行。请用助人概念和三阶段模型说明咨询师应如何回应。', NULL, '{"reference":"参考要点：先说明助人和心理咨询的合作性质，不替当事人做决定；建立联盟并澄清其真实目标；探索离职困扰、价值、资源与风险；在领悟阶段识别模式和冲突；在行动阶段比较方案、制定可检验的小步骤；持续根据反馈评估效果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9baac9c7-503d-5bce-b9bd-507bc9586699'::uuid, '42e53d60-948d-5de5-a549-efb55d27725e'::uuid, 'case', '案例题：咨询师在使用“助人效果评估”时采用了以下做法：“只凭咨询师感觉良好或当事人礼貌回应判断有效。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“助人效果评估”使用成了常见误区。规范依据是：通过当事人反馈、目标进展、功能变化和会谈过程信息持续判断助人是否有效。可改为：定期询问会谈是否有帮助、目标是否变化，并根据反馈调整；向来访者说明时可表达为：“我会定期询问哪些部分有帮助、哪些没有，以便及时调整。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c3ffdeea-d764-5dd4-b6be-11d1c2767a90'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '下列哪一概念最符合这一描述：“咨询师在教育训练、知识、技能和经验范围内提供服务，并持续维护专业能力。”？', '[{"key":"A","text":"专业胜任力"},{"key":"B","text":"反移情触点"},{"key":"C","text":"文化谦逊"},{"key":"D","text":"专业边界"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“专业胜任力”。应用提示：遇到不熟悉的高风险问题时先咨询督导并考虑转介。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ab032a63-5323-5e5d-b2e1-8f0edbdc74e3'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '下列哪一概念最符合这一描述：“咨询师识别自己的情绪、需要、价值观、偏见和身体反应，以及它们对会谈的影响。”？', '[{"key":"A","text":"文化谦逊"},{"key":"B","text":"自我觉察"},{"key":"C","text":"专业边界"},{"key":"D","text":"督导"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“自我觉察”。应用提示：发现自己急于说服当事人时，暂停并分辨这是当事人需要还是自己的焦虑。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4b7f697a-3b86-5e8d-8ee1-7786e39db3c2'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '会谈情境：对某类当事人异常保护或厌烦时，通过记录和督导理解反应。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"督导"},{"key":"B","text":"自我关照"},{"key":"C","text":"反移情触点"},{"key":"D","text":"专业胜任力"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“反移情触点”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
