insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ec327a77-be55-501e-b1a4-a3222959862c'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'blank', '请依据本章学习主线补全工作流程：检查胜任力与状态 → 识别个人触点和偏见 → 理解文化情境 → ____ → 使用督导并持续自我关照。', NULL, '{"correct":["明确边界"]}'::jsonb, '本章流程中该环节是“明确边界”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
