insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b641096c-7b28-5f19-ad98-1f50e188cbe5'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'blank', '请依据本章学习主线补全工作流程：观察语言与非语言线索 → 提出试探性情感词 → 核对准确性与强度 → ____ → 调节深度。', NULL, '{"correct":["探索触发和意义"]}'::jsonb, '本章流程中该环节是“探索触发和意义”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
