insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5e93af40-67cb-5f14-bf54-e0bb0540dee8'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '会谈情境：邀请当事人为模式命名、补充证据并寻找例外。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"协同建构"},{"key":"B","text":"领悟阶段"},{"key":"C","text":"模式识别"},{"key":"D","text":"新视角"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“协同建构”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
