insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cf8c2584-3b5b-51bc-9659-f8a40daa58cd'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '咨询师向来访者说明：“如果你愿意，我想把几个线索连起来提出一个初步理解。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"模式识别"},{"key":"B","text":"领悟时机"},{"key":"C","text":"新视角"},{"key":"D","text":"领悟假设"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“领悟时机”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cf1f6453-bd15-5dcc-9414-b73905812e7d'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '围绕“领悟的行动指向”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"理解回避模式后讨论下一次如何识别并暂停旧反应。"},{"key":"B","text":"依据概念进行判断：有效领悟应能帮助当事人看到选择、目标或可尝试的新反应。"},{"key":"C","text":"把“知道原因”本身当作改变完成。"},{"key":"D","text":"向来访者说明：理解模式是开始，接下来我们还要看看你想怎样回应得不同。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：把“知道原因”本身当作改变完成。。规范依据是：有效领悟应能帮助当事人看到选择、目标或可尝试的新反应。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d5de0fd2-b942-57c3-bc95-9848d8e39641'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"把不同关系中的相似反应联系起来，讨论其功能与代价。"},{"key":"B","text":"这个“先离开以免被抛下”的方式似乎在几个场景都出现，你怎么看？"},{"key":"C","text":"用积极思考否认现实困难和痛苦。"},{"key":"D","text":"以专业权威要求当事人接受解释。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“领悟阶段”的规范应用，B体现向来访者说明“模式识别”时的合作性表达；C、D分别是“新视角”和“领悟假设”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5cfc1f2a-1629-5983-82ef-77c0ff8fa32b'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"从“我太脆弱”转向“回避曾保护我，但现在限制了连接”。"},{"key":"B","text":"这只是一个暂时的猜想，你最有资格判断它是否贴近你的经验。"},{"key":"C","text":"咨询师垄断解释，或完全不提供任何专业反馈。"},{"key":"D","text":"为了显示专业而过早解释，或一直等待完美时机不工作。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“新视角”的规范应用，B体现向来访者说明“领悟假设”时的合作性表达；C、D分别是“协同建构”和“领悟时机”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8c72b3e2-8291-5dff-bbbc-04f1d428994b'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"邀请当事人为模式命名、补充证据并寻找例外。"},{"key":"B","text":"如果你愿意，我想把几个线索连起来提出一个初步理解。"},{"key":"C","text":"把“知道原因”本身当作改变完成。"},{"key":"D","text":"把领悟理解为咨询师揭示唯一真相。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“协同建构”的规范应用，B体现向来访者说明“领悟时机”时的合作性表达；C、D分别是“领悟的行动指向”和“领悟阶段”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d5de8fa4-585b-5d36-afd5-4a82b6e0e756'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'blank', '请依据本章学习主线补全工作流程：汇总探索材料 → ____ → 提出可检验假设 → 邀请当事人修正 → 联系目标与改变可能。', NULL, '{"correct":["识别重复模式与冲突"]}'::jsonb, '本章流程中该环节是“识别重复模式与冲突”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
