insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0aa0856b-c472-5126-a8b6-4a9704e721eb'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'blank', '请依据本章学习主线补全工作流程：汇总探索材料 → 识别重复模式与冲突 → 提出可检验假设 → ____ → 联系目标与改变可能。', NULL, '{"correct":["邀请当事人修正"]}'::jsonb, '本章流程中该环节是“邀请当事人修正”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
