on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0d0fba57-0dc6-5893-a4b3-558a46c82bdb'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'short', '简答题：领悟阶段概述包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：领悟阶段、模式识别、新视角、领悟假设、协同建构、领悟时机、领悟的行动指向。\n2）本章目标：理解领悟阶段如何通过合作形成新的视角、识别模式和理解关系，使探索材料转化为可用的意义。\n3）作答不能只罗列名称，还应依据“汇总探索材料 → 识别重复模式与冲突 → 提出可检验假设 → 邀请当事人修正 → 联系目标与改变可能。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e29d2238-3422-5605-a607-3a23e842fc48'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'short', '简答题：说明“领悟阶段”与“领悟假设”各自的含义，并指出在领悟阶段概述中的应用要点。', NULL, '{"reference":"参考要点：\n1）领悟阶段：在探索基础上帮助当事人形成新的理解、发现模式和意义，并为行动建立方向的阶段。\n2）领悟假设：咨询师依据材料提出的暂时性解释，需要与当事人共同检验和修正。\n3）应用：把不同关系中的相似反应联系起来，讨论其功能与代价。\n4）应用：使用“我有一个猜想”并询问符合程度和例外。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1e7b25da-747b-52d2-8bad-c1087af7bed5'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'short', '简答题：如果来访者询问“为什么要使用协同建构和领悟时机”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）协同建构：我们把各自看到的线索放在一起，形成一个对你有用的理解。\n2）领悟时机：如果你愿意，我想把几个线索连起来提出一个初步理解。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('68428d50-eef8-5d09-b83f-5c6a0121380d'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'case', '案例题：当事人逐渐发现自己在工作和亲密关系中都会先贬低别人再退出，以避免可能的拒绝。请说明如何在领悟阶段共同形成理解。', NULL, '{"reference":"参考要点：汇总多情境证据并识别重复模式；提出暂时性、非定论的领悟假设；理解该模式过去的保护功能和当前代价；邀请当事人修正、寻找例外和文化意义；联系其关系目标，形成可进入行动阶段的方向。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c914853a-7b5c-5fb3-ad0c-7986bc049836'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'case', '案例题：咨询师在使用“领悟的行动指向”时采用了以下做法：“把“知道原因”本身当作改变完成。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“领悟的行动指向”使用成了常见误区。规范依据是：有效领悟应能帮助当事人看到选择、目标或可尝试的新反应。可改为：理解回避模式后讨论下一次如何识别并暂停旧反应；向来访者说明时可表达为：“理解模式是开始，接下来我们还要看看你想怎样回应得不同。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('98b13c52-c54e-5ba1-a1c8-53e1be69b01d'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '下列哪一概念最符合这一描述：“以尊重和合作方式指出限制性信念、回避或不一致，促进当事人检验原有模式。”？', '[{"key":"A","text":"挑战"},{"key":"B","text":"支持性对质"},{"key":"C","text":"信念检验"},{"key":"D","text":"挑战时机"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“挑战”。应用提示：在充分共情后邀请当事人检查“必须让所有人满意”的现实性。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0044d31c-fe3e-5cb6-a15f-eaf559611855'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '下列哪一概念最符合这一描述：“当事人的言语、情感、行为、目标或结果之间存在可观察的差异。”？', '[{"key":"A","text":"信念检验"},{"key":"B","text":"不一致"},{"key":"C","text":"挑战时机"},{"key":"D","text":"挑战后的反应"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“不一致”。应用提示：指出“说不在乎”与明显紧张和反复确认之间的差距。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d14be633-6e80-5784-9ee3-c950560893e2'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '会谈情境：先肯定保护功能，再指出该方式与亲密目标冲突。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"挑战后的反应"},{"key":"B","text":"挑战与共情平衡"},{"key":"C","text":"支持性对质"},{"key":"D","text":"挑战"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“支持性对质”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5e532829-0e55-5ad6-8d5d-6d4f1808bd2b'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '会谈情境：询问“所有人都必须满意”的证据、代价和例外。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"挑战与共情平衡"},{"key":"B","text":"挑战"},{"key":"C","text":"不一致"},{"key":"D","text":"信念检验"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“信念检验”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f8e330f9-0f41-58f9-a4b0-28e38c7eb1fc'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '会谈情境：当事人情绪稳定并已觉察矛盾时提出差异。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"挑战时机"},{"key":"B","text":"挑战"},{"key":"C","text":"不一致"},{"key":"D","text":"支持性对质"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“挑战时机”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('070c165e-3ea8-5a7c-af21-37e0e976b601'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '咨询师向来访者说明：“刚才的话似乎让你退了一下，我想先了解它对你的影响。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"不一致"},{"key":"B","text":"挑战后的反应"},{"key":"C","text":"支持性对质"},{"key":"D","text":"信念检验"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“挑战后的反应”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b9539af4-12dd-5cc8-931b-28d8e2356a7e'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'single', '围绕“挑战与共情平衡”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"用“既……又……”表达保护功能与改变代价。"},{"key":"B","text":"依据概念进行判断：既保持对当事人经验的理解，也不回避指出阻碍目标的模式。"},{"key":"C","text":"向来访者说明：我能理解你为什么这样保护自己，同时也想和你看看它现在带来的限制。"},{"key":"D","text":"只共情不碰困难，或只挑战不承接体验。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：只共情不碰困难，或只挑战不承接体验。。规范依据是：既保持对当事人经验的理解，也不回避指出阻碍目标的模式。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('450904e5-b77b-58c4-8cc5-02942f4e38c5'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"在充分共情后邀请当事人检查“必须让所有人满意”的现实性。"},{"key":"B","text":"你说不在乎，但身体似乎很紧张，我想知道这两部分怎样同时存在。"},{"key":"C","text":"用羞辱、讽刺或权力压迫来制造改变。"},{"key":"D","text":"用咨询师价值观直接替换当事人信念。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“挑战”的规范应用，B体现向来访者说明“不一致”时的合作性表达；C、D分别是“支持性对质”和“信念检验”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('daa6ea52-8f0a-5d91-b230-d2a22c5b3b33'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"先肯定保护功能，再指出该方式与亲密目标冲突。"},{"key":"B","text":"我们不是要强迫你换想法，而是看看这个信念是否准确、是否对你有帮助。"},{"key":"C","text":"在危机、失控或联盟脆弱时连续强硬对质。"},{"key":"D","text":"把防御视为挑战成功的证明。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“支持性对质”的规范应用，B体现向来访者说明“信念检验”时的合作性表达；C、D分别是“挑战时机”和“挑战后的反应”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cb7f6c1b-156c-548f-9f35-da5e1f9e5d48'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人情绪稳定并已觉察矛盾时提出差异。"},{"key":"B","text":"刚才的话似乎让你退了一下，我想先了解它对你的影响。"},{"key":"C","text":"只共情不碰困难，或只挑战不承接体验。"},{"key":"D","text":"把挑战当辩论、训斥或证明咨询师正确。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“挑战时机”的规范应用，B体现向来访者说明“挑战后的反应”时的合作性表达；C、D分别是“挑战与共情平衡”和“挑战”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6558a89f-bb8d-502d-a9f2-d6ee4b48e4ba'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认关系基础 → ____ → 说明关切而非评判 → 邀请当事人反应 → 修复联盟并深化理解。', NULL, '{"correct":["描述可观察的不一致"]}'::jsonb, '本章流程中该环节是“描述可观察的不一致”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
