insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c3363b3a-d272-51b5-aaf1-21239840fc0b'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认关系基础 → 描述可观察的不一致 → 说明关切而非评判 → 邀请当事人反应 → ____。', NULL, '{"correct":["修复联盟并深化理解"]}'::jsonb, '本章流程中该环节是“修复联盟并深化理解”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
