insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5b0913b5-d91a-544b-8ead-9ef5b9a51b47'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '咨询师向来访者说明：“我们先从你已经能观察到的部分开始，不需要一次解释所有原因。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"解释焦点"},{"key":"B","text":"解释深度"},{"key":"C","text":"试探性语言"},{"key":"D","text":"解释证据"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“解释深度”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fa18c04e-0afd-54f2-b107-98000923768b'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '围绕“解释检验”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"当事人不同意就认定其阻抗或缺乏领悟。"},{"key":"B","text":"询问解释最贴近和最不贴近的部分，并观察是否带来新理解。"},{"key":"C","text":"依据概念进行判断：通过当事人的情绪、认同、反例和后续行为判断解释是否有用。"},{"key":"D","text":"向来访者说明：这个理解中哪些部分有共鸣，哪些不符合？你的不同意见很重要。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：当事人不同意就认定其阻抗或缺乏领悟。。规范依据是：通过当事人的情绪、认同、反例和后续行为判断解释是否有用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('417114a5-ed4b-5ec9-be03-99bb0f555048'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"连接早期被批评经验、当前完美要求和回避失败的模式。"},{"key":"B","text":"我们先只看这个反复出现的回避方式，看看它在保护什么。"},{"key":"C","text":"用“你就是因为……”封闭讨论。"},{"key":"D","text":"只凭一个细节进行深层因果推断。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“解释”的规范应用，B体现向来访者说明“解释焦点”时的合作性表达；C、D分别是“试探性语言”和“解释证据”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('facbefdc-a243-540b-a1ff-efb1366a9664'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"说“我有一个不确定的猜想，你听听看”。"},{"key":"B","text":"我想到这个联系，是因为你在三个场景中都描述了相似反应。"},{"key":"C","text":"只把症状视为坏习惯或缺陷。"},{"key":"D","text":"越深层、越复杂的解释就一定越好。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“试探性语言”的规范应用，B体现向来访者说明“解释证据”时的合作性表达；C、D分别是“功能性理解”和“解释深度”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b65a9240-30ee-58c1-a9b9-f2699d88ca7a'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"理解讨好既减少冲突又损害真实表达。"},{"key":"B","text":"我们先从你已经能观察到的部分开始，不需要一次解释所有原因。"},{"key":"C","text":"当事人不同意就认定其阻抗或缺乏领悟。"},{"key":"D","text":"把解释当作不可质疑的诊断结论。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“功能性理解”的规范应用，B体现向来访者说明“解释深度”时的合作性表达；C、D分别是“解释检验”和“解释”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9a0aff93-e5d5-5fca-8ead-245b5301044c'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'blank', '请依据本章学习主线补全工作流程：收集充分材料 → ____ → 用试探语言提出 → 说明证据和功能 → 邀请反应 → 根据反馈修正。', NULL, '{"correct":["选择解释焦点"]}'::jsonb, '本章流程中该环节是“选择解释焦点”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8b9e2746-2cef-5c38-9a22-018cd04d4d09'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'blank', '请依据本章学习主线补全工作流程：收集充分材料 → 选择解释焦点 → 用试探语言提出 → ____ → 邀请反应 → 根据反馈修正。', NULL, '{"correct":["说明证据和功能"]}'::jsonb, '本章流程中该环节是“说明证据和功能”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('28b5724d-4c6f-50f5-8df3-6f207007018c'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'blank', '请依据本章学习主线补全工作流程：收集充分材料 → 选择解释焦点 → 用试探语言提出 → 说明证据和功能 → 邀请反应 → ____。', NULL, '{"correct":["根据反馈修正"]}'::jsonb, '本章流程中该环节是“根据反馈修正”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c4bbfe40-97c4-5c9c-aec0-449cd5f37dba'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'short', '简答题：解释的技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：解释、解释焦点、试探性语言、解释证据、功能性理解、解释深度、解释检验。\n2）本章目标：学习以暂时、可检验和贴近材料的方式提出解释，帮助当事人理解行为、情感、关系与早期经验之间的联系。\n3）作答不能只罗列名称，还应依据“收集充分材料 → 选择解释焦点 → 用试探语言提出 → 说明证据和功能 → 邀请反应 → 根据反馈修正。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aebf731b-0a48-53e9-9cc5-5a1e79b318de'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'short', '简答题：说明“解释”与“解释证据”各自的含义，并指出在解释的技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）解释：咨询师把分散材料连接成关于原因、功能、关系或模式的暂时性理解。\n2）解释证据：解释应建立在多个会谈材料、重复模式和当事人体验上，而非咨询师想象。\n3）应用：连接早期被批评经验、当前完美要求和回避失败的模式。\n4）应用：列出几个相关事件并邀请当事人补充或反驳。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0f086123-cade-52f1-8fe3-6d2eb59abad1'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'short', '简答题：如果来访者询问“为什么要使用功能性理解和解释深度”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）功能性理解：这个方式可能曾帮助你保持安全，我们也可以看看它现在的代价。\n2）解释深度：我们先从你已经能观察到的部分开始，不需要一次解释所有原因。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1f7c31bf-bb70-5631-9e63-470776a6f283'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'case', '案例题：咨询师注意到当事人每当工作获得肯定就立即贬低成绩，并想起其童年只有第一名才被认可。请构造一个合适解释并说明检验方式。', NULL, '{"reference":"参考要点：用试探性语言连接多次自我贬低、条件性认可与完美要求；说明该方式可能保护其免受更高期待或失败羞耻；避免断言童年是唯一原因；邀请当事人判断贴合度、提出反例并观察情绪；根据反馈修正解释并联系改变方向。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('91a2c92f-f2e7-5e0f-a3de-14884d268f86'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'case', '案例题：咨询师在使用“解释检验”时采用了以下做法：“当事人不同意就认定其阻抗或缺乏领悟。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“解释检验”使用成了常见误区。规范依据是：通过当事人的情绪、认同、反例和后续行为判断解释是否有用。可改为：询问解释最贴近和最不贴近的部分，并观察是否带来新理解；向来访者说明时可表达为：“这个理解中哪些部分有共鸣，哪些不符合？你的不同意见很重要。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bb4005d8-5999-5ac8-b9cb-2e3f3a7c7d85'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '下列哪一概念最符合这一描述：“会谈中影响信任、合作或情感联结的具体互动，包括靠近、撤退、误解和修复。”？', '[{"key":"A","text":"治疗关系事件"},{"key":"B","text":"撤退型破裂"},{"key":"C","text":"对抗型破裂"},{"key":"D","text":"关系修复"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“治疗关系事件”。应用提示：当事人突然沉默后，咨询师停下来询问刚才发生了什么。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a393c9cc-2718-5ca4-838a-339201d94b9a'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '下列哪一概念最符合这一描述：“目标、任务或情感联结出现紧张、撤退或对抗，影响合作的状态。”？', '[{"key":"A","text":"对抗型破裂"},{"key":"B","text":"联盟破裂"},{"key":"C","text":"关系修复"},{"key":"D","text":"关系中的即时性"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“联盟破裂”。应用提示：当事人迟到、表面同意或直接质疑时检查联盟。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c6fca4e1-6d04-5707-9354-6854d85de34d'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '会谈情境：注意“都可以”背后的退缩并温和邀请真实意见。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"关系中的即时性"},{"key":"B","text":"关系模式泛化"},{"key":"C","text":"撤退型破裂"},{"key":"D","text":"治疗关系事件"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“撤退型破裂”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
