insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('eddbb72f-8e24-5548-9325-64546927f661'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '会谈情境：当挑战后出现羞耻和撤退时立即放慢并修复。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"向行动过渡"},{"key":"B","text":"领悟目标"},{"key":"C","text":"技术匹配"},{"key":"D","text":"反应监测"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“反应监测”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
