insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a2dc980e-3238-5930-a403-060bb33be778'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '会谈情境：让当事人用自己的话总结模式并找出最近例子。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"领悟巩固"},{"key":"B","text":"领悟目标"},{"key":"C","text":"技术匹配"},{"key":"D","text":"由浅入深"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“领悟巩固”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
