insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0c87fb65-a8ce-5c1f-b36d-d37ddd6586c8'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '会谈情境：共同列出沟通、准备、寻求支持和环境调整等方案。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"行动反馈循环"},{"key":"B","text":"行动阶段"},{"key":"C","text":"行动准备度"},{"key":"D","text":"方案生成"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“方案生成”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
