insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dab48568-bb76-51e7-908e-14033876d4e9'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '咨询师向来访者说明：“我们先设计一个足够小、你有把握完成的步骤。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"行动准备度"},{"key":"B","text":"小步骤"},{"key":"C","text":"具体目标"},{"key":"D","text":"方案生成"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“小步骤”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f80cd421-774a-5349-9cbe-5a28ea82b488'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '围绕“行动反馈循环”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"下次会谈比较预期与实际结果并修订计划。"},{"key":"B","text":"依据概念进行判断：实施后记录结果、情绪和障碍，再据此巩固、调整或更换方案。"},{"key":"C","text":"向来访者说明：无论是否完成，结果都会提供信息，帮助我们调整下一步。"},{"key":"D","text":"任务完成与否是唯一指标，未完成就算失败。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：任务完成与否是唯一指标，未完成就算失败。。规范依据是：实施后记录结果、情绪和障碍，再据此巩固、调整或更换方案。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1c4103fa-9451-55fc-947c-e95efc552990'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"围绕已识别的回避模式设计一次可完成的沟通尝试。"},{"key":"B","text":"在决定行动前，我们先看看你有多想改变、有什么资源和顾虑。"},{"key":"C","text":"目标由咨询师决定，或使用无法观察的空泛词。"},{"key":"D","text":"只给一个“正确方案”并要求执行。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“行动阶段”的规范应用，B体现向来访者说明“行动准备度”时的合作性表达；C、D分别是“具体目标”和“方案生成”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('98b91a07-8bf8-59d6-a90d-544f368779e8'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"把“更自信”转为“本周会议至少表达一次不同意见”。"},{"key":"B","text":"我们先不急着判断，尽可能列出几种做法，再比较。"},{"key":"C","text":"只看短期舒服程度或咨询师个人偏好。"},{"key":"D","text":"一次要求彻底改变，失败后归因为缺乏动力。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“具体目标”的规范应用，B体现向来访者说明“方案生成”时的合作性表达；C、D分别是“方案评估”和“小步骤”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1d6814e7-4be3-58c2-a1f8-bfa226a25403'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"对离职方案同时评估经济、健康、关系和替代选择。"},{"key":"B","text":"我们先设计一个足够小、你有把握完成的步骤。"},{"key":"C","text":"任务完成与否是唯一指标，未完成就算失败。"},{"key":"D","text":"把行动等同于咨询师给建议或当事人立刻做巨大改变。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“方案评估”的规范应用，B体现向来访者说明“小步骤”时的合作性表达；C、D分别是“行动反馈循环”和“行动阶段”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ffd88b0e-d395-5189-8a78-816b2c1bc995'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认行动准备度 → ____ → 生成多个方案 → 评估可行性与风险 → 选择小步骤 → 实施、反馈和修订。', NULL, '{"correct":["设定具体目标"]}'::jsonb, '本章流程中该环节是“设定具体目标”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e0c813be-f248-54be-ad70-cb763391a800'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认行动准备度 → 设定具体目标 → 生成多个方案 → ____ → 选择小步骤 → 实施、反馈和修订。', NULL, '{"correct":["评估可行性与风险"]}'::jsonb, '本章流程中该环节是“评估可行性与风险”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f2d6a34f-948d-5285-805b-293cd723e1ea'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认行动准备度 → 设定具体目标 → 生成多个方案 → 评估可行性与风险 → 选择小步骤 → ____。', NULL, '{"correct":["实施、反馈和修订"]}'::jsonb, '本章流程中该环节是“实施、反馈和修订”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ffc7d0d8-ab05-5b87-b8ee-e96ea62a0d32'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'short', '简答题：行动阶段概述包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：行动阶段、行动准备度、具体目标、方案生成、方案评估、小步骤、行动反馈循环。\n2）本章目标：理解行动阶段如何把领悟转化为目标、方案、技能和现实生活中的练习，并通过反馈持续调整。\n3）作答不能只罗列名称，还应依据“确认行动准备度 → 设定具体目标 → 生成多个方案 → 评估可行性与风险 → 选择小步骤 → 实施、反馈和修订。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('674ffe7a-4ccd-5703-acfd-dd5dedbf1bc0'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'short', '简答题：说明“行动阶段”与“方案生成”各自的含义，并指出在行动阶段概述中的应用要点。', NULL, '{"reference":"参考要点：\n1）行动阶段：把探索和领悟转化为新行为、技能、环境调整与持续练习的阶段。\n2）方案生成：在评估前尽量产生多个可能行动，扩大选择而不是过早锁定一个答案。\n3）应用：围绕已识别的回避模式设计一次可完成的沟通尝试。\n4）应用：共同列出沟通、准备、寻求支持和环境调整等方案。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6bc9cebe-9433-5658-b6ad-e43226e78ec9'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'short', '简答题：如果来访者询问“为什么要使用方案评估和小步骤”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）方案评估：每个方案都有收益和代价，我们一起看哪些最符合你的现实和价值。\n2）小步骤：我们先设计一个足够小、你有把握完成的步骤。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('af2874de-f035-5457-854b-5a4e21c24d9e'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'case', '案例题：当事人理解自己害怕拒绝，却提出“从明天起我要对所有人说不”。请评估其行动准备度并把目标转化为合理计划。', NULL, '{"reference":"参考要点：认可改变愿望但评估信心、风险和资源；把全或无目标具体化；生成多个练习方案；从低风险关系和小请求开始；明确时间、行为和反馈记录；讨论失败与复发；由当事人选择，不以咨询师命令替代合作。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('781867b1-8cd1-5bfc-9020-94390fb62050'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'case', '案例题：咨询师在使用“行动反馈循环”时采用了以下做法：“任务完成与否是唯一指标，未完成就算失败。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“行动反馈循环”使用成了常见误区。规范依据是：实施后记录结果、情绪和障碍，再据此巩固、调整或更换方案。可改为：下次会谈比较预期与实际结果并修订计划；向来访者说明时可表达为：“无论是否完成，结果都会提供信息，帮助我们调整下一步。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('36e273c9-4a86-569d-8ed0-154262065242'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '下列哪一概念最符合这一描述：“把改变愿望转化为具体情境中的可观察行为、频率和完成标准。”？', '[{"key":"A","text":"行为目标化"},{"key":"B","text":"示范"},{"key":"C","text":"角色演练"},{"key":"D","text":"行为反馈"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“行为目标化”。应用提示：将“少焦虑”改为“焦虑时完成三分钟呼吸并继续停留五分钟”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8d776c19-87dc-54d2-a0b1-1ef659000263'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '下列哪一概念最符合这一描述：“向当事人清楚说明技能原理、步骤、适用情境和限制。”？', '[{"key":"A","text":"角色演练"},{"key":"B","text":"技能教学"},{"key":"C","text":"行为反馈"},{"key":"D","text":"实施意图"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“技能教学”。应用提示：教授表达请求时先解释结构，再示范。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6bf6cf6e-8c9b-5798-acd7-71006d86ad72'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '会谈情境：示范一次坚定而尊重的拒绝。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"实施意图"},{"key":"B","text":"障碍预演"},{"key":"C","text":"示范"},{"key":"D","text":"行为目标化"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“示范”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
