insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a134c60f-db81-5f01-9498-e55132c51229'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '会谈情境：咨询师扮演上司，与当事人演练表达不同意见。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"障碍预演"},{"key":"B","text":"行为目标化"},{"key":"C","text":"技能教学"},{"key":"D","text":"角色演练"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“角色演练”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
