insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ff5da516-95b7-5356-bd06-4cc7e6b059ba'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '会谈情境：先指出清晰表达，再建议放慢语速和补充请求。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"行为反馈"},{"key":"B","text":"行为目标化"},{"key":"C","text":"技能教学"},{"key":"D","text":"示范"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“行为反馈”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
