insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('64884993-b0f7-5675-85fd-62237e2eb69f'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '会谈情境：主动邀请讨论对结束的复杂感受。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"非计划终止"},{"key":"B","text":"计划性结束"},{"key":"C","text":"结束评估"},{"key":"D","text":"结束情感"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“结束情感”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
