insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f826d8ae-f473-5ab6-8c2b-891ef5cac5b6'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '会谈情境：制作触发—信号—应对—求助的书面计划。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"复发预防"},{"key":"B","text":"计划性结束"},{"key":"C","text":"结束评估"},{"key":"D","text":"回顾与巩固"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“复发预防”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
