insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('78904116-eea4-5861-a15a-d6171cd5d967'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '咨询师向来访者说明：“结束后你仍可以使用这些支持；如果出现哪些情况，需要及时联系相应资源。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"结束评估"},{"key":"B","text":"资源与转介"},{"key":"C","text":"回顾与巩固"},{"key":"D","text":"结束情感"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“资源与转介”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('91983518-f25d-5a11-a2ea-c178a72a6255'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '围绕“非计划终止”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"高风险当事人失联时按约定和机构流程进行安全处置。"},{"key":"B","text":"依据概念进行判断：当事人突然停止、失联或因外部原因结束时，在伦理和设置范围内尝试联系、评估风险并记录。"},{"key":"C","text":"向来访者说明：如果你想提前结束，可以告诉我；我们尽量安排一次总结和安全计划。"},{"key":"D","text":"反复追踪侵犯边界，或因感到被拒绝而完全不处理。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：反复追踪侵犯边界，或因感到被拒绝而完全不处理。。规范依据是：当事人突然停止、失联或因外部原因结束时，在伦理和设置范围内尝试联系、评估风险并记录。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5ae0f251-060c-5a88-a200-45d5d17d671f'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"在剩余数次会谈时开始讨论结束日期和任务。"},{"key":"B","text":"我们会一起看哪些目标已实现、哪些仍需支持，再决定结束安排。"},{"key":"C","text":"把成果全部归功于咨询师或技术。"},{"key":"D","text":"只强调庆祝，回避负面或矛盾情绪。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“计划性结束”的规范应用，B体现向来访者说明“结束评估”时的合作性表达；C、D分别是“回顾与巩固”和“结束情感”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ecb8ed91-006d-5740-a996-b7b1d73c669d'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"让当事人列出最有用的方法和如何继续使用。"},{"key":"B","text":"结束可能同时让人轻松和不舍，这些感受都可以在这里谈。"},{"key":"C","text":"承诺问题永不复发，或把波动视为失败。"},{"key":"D","text":"结束就完全切断，不提供必要资源；或制造持续依赖。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“回顾与巩固”的规范应用，B体现向来访者说明“结束情感”时的合作性表达；C、D分别是“复发预防”和“资源与转介”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c8f9ded2-a5d4-5375-b814-2455611d5274'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"制作触发—信号—应对—求助的书面计划。"},{"key":"B","text":"结束后你仍可以使用这些支持；如果出现哪些情况，需要及时联系相应资源。"},{"key":"C","text":"反复追踪侵犯边界，或因感到被拒绝而完全不处理。"},{"key":"D","text":"等到最后一次才告知，或无限延长以避免分离。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“复发预防”的规范应用，B体现向来访者说明“资源与转介”时的合作性表达；C、D分别是“非计划终止”和“计划性结束”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b0d67ba8-99be-58e6-abe3-f2ab937a4118'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'blank', '请依据本章学习主线补全工作流程：提前讨论结束 → ____ → 处理分离情感 → 总结有效方法 → 制定复发预防与资源计划 → 完成告别和随访安排。', NULL, '{"correct":["回顾目标与变化"]}'::jsonb, '本章流程中该环节是“回顾目标与变化”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
