insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9b8be1e1-ca5e-59a9-b483-565ef7328ab3'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'blank', '请依据本章学习主线补全工作流程：提前讨论结束 → 回顾目标与变化 → 处理分离情感 → ____ → 制定复发预防与资源计划 → 完成告别和随访安排。', NULL, '{"correct":["总结有效方法"]}'::jsonb, '本章流程中该环节是“总结有效方法”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
