insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9c2fc69e-fa7b-51f4-90cf-5084705305eb'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'blank', '请依据本章学习主线补全工作流程：提前讨论结束 → 回顾目标与变化 → 处理分离情感 → 总结有效方法 → 制定复发预防与资源计划 → ____。', NULL, '{"correct":["完成告别和随访安排"]}'::jsonb, '本章流程中该环节是“完成告别和随访安排”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
