insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('218d5685-ec60-520e-bcff-2359776b0c91'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'short', '简答题：结束咨询包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：计划性结束、结束评估、回顾与巩固、结束情感、复发预防、资源与转介、非计划终止。\n2）本章目标：把结束视为助人过程的重要阶段，通过计划、回顾、情感处理、复发预防和资源安排促进自主与持续改变。\n3）作答不能只罗列名称，还应依据“提前讨论结束 → 回顾目标与变化 → 处理分离情感 → 总结有效方法 → 制定复发预防与资源计划 → 完成告别和随访安排。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('43607d09-f8aa-56e4-a6f3-326fefd592f8'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'short', '简答题：说明“计划性结束”与“结束情感”各自的含义，并指出在结束咨询中的应用要点。', NULL, '{"reference":"参考要点：\n1）计划性结束：根据目标进展、时间和服务设置提前协商结束，而非突然终止。\n2）结束情感：结束可能引发不舍、焦虑、愤怒、轻松或被抛弃感，需要被允许和理解。\n3）应用：在剩余数次会谈时开始讨论结束日期和任务。\n4）应用：主动邀请讨论对结束的复杂感受。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9277e261-e59a-5061-acd3-982e32d12fba'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'short', '简答题：如果来访者询问“为什么要使用复发预防和资源与转介”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）复发预防：以后有波动并不等于前功尽弃，重要的是尽早识别并使用计划。\n2）资源与转介：结束后你仍可以使用这些支持；如果出现哪些情况，需要及时联系相应资源。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('25abad54-56f6-5e96-bdaa-ad648e1feca8'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'case', '案例题：长期来访者在目标明显改善后说“我一想到结束就觉得你也会抛弃我”，并要求无限期继续。请设计结束阶段工作。', NULL, '{"reference":"参考要点：共情并允许分离与被抛弃感；把结束作为关系模式的工作机会；共同评估目标、风险和自主能力；提前计划结束时间；回顾当事人贡献和有效技能；制定复发预防、资源和求助条件；保持边界，不因咨询师或当事人的不舍无限延长。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('18a0c8f2-8dc2-57fc-af9b-d0f73485baac'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'case', '案例题：咨询师在使用“非计划终止”时采用了以下做法：“反复追踪侵犯边界，或因感到被拒绝而完全不处理。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“非计划终止”使用成了常见误区。规范依据是：当事人突然停止、失联或因外部原因结束时，在伦理和设置范围内尝试联系、评估风险并记录。可改为：高风险当事人失联时按约定和机构流程进行安全处置；向来访者说明时可表达为：“如果你想提前结束，可以告诉我；我们尽量安排一次总结和安全计划。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;

commit;
